<script setup lang="ts">
import { useCmsI18n } from '@/composables/useCmsI18n';
import { onMounted, ref } from 'vue';
import { cmsApi } from '../api';
import type { Scope, Settings, ContentModel, FormData } from '../types';
import { useOperation } from './useOperation';
const { t } = useCmsI18n();
const props = defineProps<{scope:Scope;settings:Pick<Settings,'models'>;can:(permission:string)=>boolean;isSuper:boolean}>();const emit=defineEmits<{updated:[]}>();
const {busy,error,run}=useOperation();const rows=ref<ContentModel[]>([]),dialog=ref(false),form=ref<FormData>({});
async function load(){ if (!(props.can('cms:model:list'))) return;await run(async()=>{rows.value=await cmsApi.models(props.scope);});}
function open(row?:ContentModel){ if (!(props.isSuper && props.can('cms:model:save'))) return;form.value=row?{id:row.id,code:row.code,name:row.name,status:Number(row.status),fields:JSON.parse(JSON.stringify(row.schema.field_schema))}:{code:'',name:'',status:1,fields:[]};dialog.value=true;}
async function save(){ if (!(props.isSuper && props.can('cms:model:save'))) return;await run(async()=>{await cmsApi.saveModel(form.value);dialog.value=false;await load();});}
async function toggle(row:ContentModel,status:boolean){ if (!(props.can('cms:model:status'))) return;await run(async()=>{await cmsApi.saveSiteModel({site_id:props.scope.site_id,model_id:row.id,status:status?1:0});emit('updated');});}
async function setTemplate(row:ContentModel,value:string){ if (!(props.can('cms:model:template'))) return;await run(async()=>{await cmsApi.saveSiteModel({site_id:props.scope.site_id,model_id:row.id,status:enabled(row.id)?1:0,default_template:value});emit('updated');});}
function changeType(field:FormData){
  delete field.default;delete field.min;delete field.max;delete field.max_length;
  if(field.type==='select')field.options=[];else delete field.options;
}
function enabled(id:string){return props.settings.models.some(item=>item.model_id===id&&Number(item.status)===1);}
onMounted(load);
</script>
<template><div><el-alert v-if="error" :title="error" type="error" :closable="false" /><div class="toolbar"><el-button v-if="isSuper&&can('cms:model:save')" type="primary" @click="open()">{{ t('cms.labels.newModel') }}</el-button></div><el-table :data="rows"><el-table-column prop="name" :label="t('cms.labels.model')" /><el-table-column prop="code" :label="t('cms.labels.code')" /><el-table-column prop="current_version" :label="t('cms.labels.definitionVersion')" /><el-table-column :label="t('cms.labels.enabledForThisSite')"><template #default="{row}"><el-switch :model-value="enabled(row.id)" :disabled="!can('cms:model:status')||busy" @change="toggle(row as ContentModel,!!$event)" /></template></el-table-column><el-table-column :label="t('cms.labels.defaultDetailTemplate')" min-width="160"><template #default="{row}"><el-input :model-value="settings.models.find(item=>item.model_id===row.id)?.default_template || 'detail'" :disabled="!can('cms:model:template') || busy" @change="setTemplate(row as ContentModel, String($event))" /></template></el-table-column><el-table-column :label="t('cms.labels.actions')"><template #default="{row}"><el-button v-if="isSuper&&can('cms:model:save')" link @click="open(row as ContentModel)">{{ t('cms.labels.editFields') }}</el-button></template></el-table-column></el-table>
<el-dialog v-model="dialog" :title="t('cms.labels.contentModel')" width="min(900px, 96vw)" :close-on-click-modal="false"><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-form label-position="top"><el-form-item :label="t('cms.labels.modelCode')" required><el-input v-model="form.code" :disabled="!!form.id" /></el-form-item><el-form-item :label="t('cms.labels.modelName')" required><el-input v-model="form.name" /></el-form-item><el-alert :title="t('cms.labels.savingCreatesANewFieldDefinitionVersionExistingContent')" :closable="false" /><div class="field-card" v-for="(field,index) in form.fields" :key="index"><div class="field-row"><el-input v-model="field.name" :placeholder="t('cms.labels.fieldCode')" :aria-label="t('cms.labels.fieldValueCode2', { value1: Number(index)+1 })" /><el-input v-model="field.label" :placeholder="t('cms.labels.fieldName')" :aria-label="t('cms.labels.fieldValueName2', { value1: Number(index)+1 })" /><el-select v-model="field.type" @change="changeType(field)"><el-option v-for="(label,type) in {text:t('cms.labels.singleLineText'),textarea:t('cms.labels.multilineText'),number:t('cms.labels.number'),boolean:t('cms.labels.switch'),select:t('cms.labels.select'),image:t('cms.labels.image'),file:t('cms.labels.file'),gallery:t('cms.labels.gallery')}" :key="type" :label="label" :value="type" /></el-select><el-checkbox v-model="field.required">{{ t('cms.labels.required') }}</el-checkbox><el-button link type="danger" @click="form.fields.splice(index,1)">{{ t('cms.labels.remove') }}</el-button></div>
<div class="field-config"><el-input v-model="field.description" :placeholder="t('cms.labels.helpText')" :aria-label="t('cms.labels.valueHelpText', { value1: field.label||t('cms.labels.field') })" maxlength="500" /><el-input v-model="field.placeholder" :placeholder="t('cms.labels.placeholder')" :aria-label="t('cms.labels.valuePlaceholder', { value1: field.label||t('cms.labels.field') })" maxlength="255" />
<template v-if="field.type==='number'"><el-input-number v-model="field.default" :placeholder="t('cms.labels.defaultValue')" :aria-label="t('cms.labels.valueDefaultValue', { value1: field.label||t('cms.labels.field') })" /><el-input-number v-model="field.min" :placeholder="t('cms.labels.minimum')" :aria-label="t('cms.labels.valueMinimum', { value1: field.label||t('cms.labels.field') })" /><el-input-number v-model="field.max" :placeholder="t('cms.labels.maximum')" :aria-label="t('cms.labels.valueMaximum', { value1: field.label||t('cms.labels.field') })" /></template>
<el-form-item v-else-if="field.type==='boolean'" :label="t('cms.labels.defaultValue')"><el-switch v-model="field.default" :aria-label="t('cms.labels.valueDefaultValue', { value1: field.label||t('cms.labels.field') })" /></el-form-item>
<template v-else-if="field.type==='select'"><el-input :model-value="(field.options||[]).join(',')" :placeholder="t('cms.labels.optionsSeparatedByCommas')" :aria-label="t('cms.labels.options')" @update:model-value="field.options=String($event).split(',').map(item=>item.trim()).filter(Boolean)" /><el-select v-model="field.default" clearable :placeholder="t('cms.labels.defaultValue')" :aria-label="t('cms.labels.defaultValue')"><el-option v-for="option in field.options" :key="option" :label="option" :value="option" /></el-select></template>
<template v-else-if="['text','textarea'].includes(field.type)"><el-input v-model="field.default" :placeholder="t('cms.labels.defaultValue')" :aria-label="t('cms.labels.valueDefaultValue', { value1: field.label||t('cms.labels.field') })" :type="field.type==='textarea'?'textarea':'text'" /><el-input-number v-model="field.max_length" :placeholder="t('cms.labels.maximumCharacters')" :aria-label="t('cms.labels.valueMaximumCharacters', { value1: field.label||t('cms.labels.field') })" :min="1" :max="field.type==='textarea'?20000:2000" :precision="0" /></template></div></div><el-button @click="form.fields.push({name:'',label:'',type:'text',required:false})">{{ t('cms.labels.addField') }}</el-button></el-form><template #footer><el-button @click="dialog=false">{{ t('cms.labels.cancel') }}</el-button><el-button v-if="isSuper && can('cms:model:save')" type="primary" :loading="busy" @click="save">{{ t('cms.labels.saveNewVersion') }}</el-button></template></el-dialog></div></template>
<style scoped>.toolbar{margin:16px 0}.field-card{border:1px solid var(--el-border-color-lighter);border-radius:6px;padding:16px;margin:14px 0}.field-config{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.field-config .el-input-number,.field-config .el-select{width:100%}.field-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}.field-row .el-input,.field-row .el-select{width:180px}</style>
